import{createStudy,clamp,lerp,downloadSVG}from'./core.js';
const study=createStudy({id:17,title:'Continuum',category:'Scroll / Position',accent:'#ffa46b',background:'#14151a',foreground:'#f6eee5'}),svg=document.querySelector('#continuum-art'),group=document.querySelector('#continuum-rings'),sections=[...document.querySelectorAll('[data-chapter]')],scene=document.querySelector('.continuum-scene');
const NS='http://www.w3.org/2000/svg';let target=0,position=0,last=-1;
for(let i=0;i<32;i++){const ring=document.createElementNS(NS,'ellipse');ring.setAttribute('fill','none');ring.setAttribute('stroke-width',i%5===0?1.6:.7);group.append(ring)}
const palettes=[['#ffae78','#191a25'],['#d4efa1','#1b2926'],['#c4b1f2','#25213a'],['#ff819b','#35202c'],['#f3cd8e','#242222']];
function measure(){const y=scrollY+72+(matchMedia('(max-width:760px)').matches?innerHeight*.57:0);let index=0;for(let i=0;i<sections.length;i++)if(sections[i].getBoundingClientRect().top+scrollY<=y)index=i;const current=sections[index],next=sections[Math.min(index+1,4)],start=current.getBoundingClientRect().top+scrollY,span=index<4?next.getBoundingClientRect().top+scrollY-start:current.offsetHeight;const value=clamp(index+(y-start)/span,0,4);if(study.running())target=value;const p=Math.round(value/4*100);document.querySelector('#continuum-percent').textContent=String(p).padStart(2,'0')+'%';document.querySelectorAll('.chapter-dots a').forEach((a,i)=>a.setAttribute('aria-current',String(i===Math.floor(value+.00001))));study.invalidate()}
function draw({dt,time}){position=lerp(position,target,dt?1-Math.exp(-dt*7):study.running()?0:1);if(Math.abs(position-target)<.0001)position=target;const chapter=Math.min(4,Math.floor(position+.00001));const [color,bg]=palettes[chapter];if(chapter!==last){scene.style.background=bg;document.querySelector('#continuum-state').textContent=String(chapter+1).padStart(2,'0')+' / '+['BEGIN','SHIFT','UNFOLD','RELEASE','RETURN'][chapter];last=chapter}const phase=position/4;for(let i=0;i<group.children.length;i++){const f=i/32;const rx=200+Math.sin(f*Math.PI+phase*3)*42,ry=32+Math.sin(phase*Math.PI)*95+f*35,angle=f*180+phase*180;const cx=400+Math.sin(f*5+phase*6)*phase*90,cy=400+(f-.5)*Math.sin(phase*Math.PI)*150;const el=group.children[i];el.setAttribute('cx',cx.toFixed(2));el.setAttribute('cy',cy.toFixed(2));el.setAttribute('rx',rx.toFixed(2));el.setAttribute('ry',ry.toFixed(2));el.setAttribute('transform',`rotate(${angle.toFixed(2)} ${cx.toFixed(2)} ${cy.toFixed(2)})`);el.setAttribute('stroke',i%6===0?'#f3eee5':color);el.setAttribute('opacity',(.45+f*.5).toFixed(2))}group.setAttribute('transform',`translate(400 400) scale(${.82+Math.sin(phase*Math.PI)*.28}) translate(-400 -400)`)}
window.addEventListener('scroll',measure,{passive:true});study.onFrame(draw);study.onResize(measure);study.onMotion(run=>{if(run)measure()});study.setReset(()=>{position=target=0;window.scrollTo({top:0,behavior:'auto'});measure()});study.setExport(()=>downloadSVG(svg,'sub-continuum.svg',{background:getComputedStyle(scene).backgroundColor}));study.cleanup(()=>window.removeEventListener('scroll',measure));
